entries[25217] = { ["name"] = "Machtwort: Schild", ["text"] = "23% von Grundmana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft eines befreundeten Ziels, um es mit einem Schild zu umhüllen und so 1144 Schaden zu absorbieren. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
entries[25218] = { ["name"] = "Machtwort: Schild", ["text"] = "23% von Grundmana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft eines befreundeten Ziels, um es mit einem Schild zu umhüllen und so 1286 Schaden zu absorbieren. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
