entries[25225] = { ["name"] = "Rüstung zerreißen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie pro Einsatz von 'Rüstung zerreißen' um 520 und verursacht ein hohes Maß an Bedrohung. Die Bedrohung wird durch Angriffskraft erhöht. Kann bis zu 5-mal angewendet werden. Hält until cancelled lang an." }
entries[25228] = { ["name"] = "Seelenverbindung", ["text"] = "Sofort\nBei Aktivierung werden 20% des von Euch erlittenen Schadens auf Euren Wichtel, Leerwandler, Sukkubus, Teufelsjäger, Eure Teufelswache oder Euren unterworfenen Dämon umgelenkt. Dieser Schaden kann nicht vermieden werden. Hält an, solange der Dämon aktiv ist und kontrolliert wird." }
entries[25229] = { ["name"] = "Juwelenschleifen", ["text"] = "Sofort\nErlaubt es einem Juwelenschleifer, Schmuck bis zu einer maximalen potenziellen Fertigkeit von 75 herzustellen. Es werden Edelsteine und Metalle benötigt, die mit der Bergbaufertigkeit gefunden wurden." }
