entries[25231] = { ["name"] = "Spalten", ["text"] = "20 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin weitreichender Angriff, der dem Ziel und\n\nGlyphe 'Spalten'\nseinen nächsten zwei Verbündeten\n\nseinem nächsten Verbündeten Waffenschaden plus 135 zufügt." }
