entries[25251] = { ["name"] = "Blutdurst", ["text"] = "30 Wut Nahkampfreichweite\nSpontanzauber 4 sek. Abklingzeit\nGreift das Ziel sofort an und verursacht (Attack power * 45 / 100) Schaden. Zusätzlich werden die nächsten erfolgreichen 0 Nahkampfangriffe 45 Gesundheit wiederherstellen. Dieser Effekt hält until cancelled lang an. Schaden basiert auf Angriffskraft." }
