entries[25266] = { ["name"] = "Spöttischer Schlag", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 2 min Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nEin spottender Angriff, der 114 Schaden und ein mittleres Maß an Bedrohung verursacht. Zwingt das Ziel 6 sec lang dazu, Angriffe auf Euch zu fokussieren." }
